void page(Director& u,int selected){u.page=selected;for(int id=200;id<=499;++id){HWND c=GetDlgItem(u.window,id);if(c)ShowWindow(c,id/100==selected+2?SW_SHOW:SW_HIDE);}}
void availability(Director& u){const bool scene=!u.scene.empty();for(int id:{111,112,210,211,212,323})EnableWindow(GetDlgItem(u.window,id),scene);const bool npc=scene && SendDlgItemMessage(u.window,301,LB_GETCURSEL,0,0)!=LB_ERR;for(int id:{321,322})EnableWindow(GetDlgItem(u.window,id),npc);for(int id:{410,411})EnableWindow(GetDlgItem(u.window,id),scene && SendDlgItemMessage(u.window,401,LB_GETCURSEL,0,0)!=LB_ERR);EnableWindow(GetDlgItem(u.window,320),scene && SendDlgItemMessage(u.window,312,CB_GETCURSEL,0,0)!=CB_ERR);}
