HWND OpenWorkspaceSceneDirector(CMainFrame& frame){WNDCLASSW cls={0};cls.lpfnWndProc=procedure;cls.hInstance=AfxGetInstanceHandle();cls.lpszClassName=L"MUSHclientSceneDirector";cls.hCursor=LoadCursor(NULL,IDC_ARROW);cls.hbrBackground=(HBRUSH)(COLOR_BTNFACE+1);RegisterClassW(&cls);Director* u=new Director();HWND w=CreateWindowExW(0,cls.lpszClassName,L"Scene director",WS_OVERLAPPEDWINDOW,CW_USEDEFAULT,CW_USEDEFAULT,1000,735,frame.GetSafeHwnd(),NULL,cls.hInstance,u);if(w){workspace_style::FitToWorkArea(w,420,380);ShowWindow(w,SW_SHOW);}else delete u;return w;}
